 import { supabase } from '../lib/supabase';

// ✅ YOUR DYNAMIC YOCO LINK
const YOCO_BASE_URL = "https://pay.yoco.com/r/X8YkjB";

export async function initiatePayment({
  amount,
  currency = 'ZAR',
  email,
  fullName,
  userId,
  communityId = null,
  type = 'community',
}) {
  try {
    // 1. Calculate fees
    const platformFee = type === 'community' ? amount * 0.30 : amount * 0.10;
    const creatorEarnings = type === 'community' ? amount * 0.70 : amount * 0.90;

    // 2. Create pending record in Supabase
    const { data: payment, error } = await supabase
      .from('subscription_payments')
      .insert({
        user_id: userId,
        community_id: communityId,
        amount: amount,
        currency: currency,
        platform_fee: platformFee,
        creator_earnings: creatorEarnings,
        type: type,
        status: 'pending'
      })
      .select()
      .single();

    if (error) throw error;

    // 3. ✅ DYNAMIC URL CONSTRUCTION
    // Yoco reads the amount in cents (R50 = 5000)
    const amountInCents = Math.round(amount * 100);
    
    // Append the amount to the base link
    const checkoutUrl = `${YOCO_BASE_URL}?amount=${amountInCents}`;

    // 4. Redirect the user to Yoco with the correct amount pre-filled
    window.location.href = checkoutUrl;

    return { success: true, paymentId: payment.id };

  } catch (error) {
    console.error('Payment error:', error);
    return { success: false, error: error.message };
  }
}
